//go:build linux

package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"net"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strings"
	"syscall"
	"time"
)

// params tell the checks what to attack. Paths and secrets are generated by
// the test on the host and are not mounted into the container.
type params struct {
	// Canary is a file on the host, absent from the container.
	Canary string `json:"canary"`
	// JobCanary is a file in another job's directory.
	JobCanary string `json:"job_canary"`
	// Secret is an environment value of another container.
	Secret string `json:"secret"`
	// Dial are addresses that must be unreachable.
	Dial []string `json:"dial"`
	// Lookup is a name that must not resolve.
	Lookup string `json:"lookup"`
	// PidsLimit is the container limit the fork bomb must not exceed.
	PidsLimit int `json:"pids_limit"`
	// SkipForkBomb leaves the fork bomb out, for runs inside a live Worker
	// whose own threads count against the same limit.
	SkipForkBomb bool `json:"skip_fork_bomb"`
}

type check struct {
	Name   string `json:"name"`
	Breach bool   `json:"breach"`
	Errno  string `json:"errno,omitempty"`
	Detail string `json:"detail,omitempty"`
}

type report struct {
	Checks []check           `json:"checks"`
	Info   map[string]string `json:"info"`
}

type listFlag []string

func (l *listFlag) String() string     { return strings.Join(*l, ",") }
func (l *listFlag) Set(v string) error { *l = append(*l, v); return nil }

func runChecks(args []string) int {
	var p params
	var dial listFlag
	fs := flag.NewFlagSet("checks", flag.ContinueOnError)
	fs.StringVar(&p.Canary, "canary", "", "host file that must not exist here")
	fs.StringVar(&p.JobCanary, "job-canary", "", "another job's file that must not exist here")
	fs.StringVar(&p.Secret, "secret", "", "another container's secret value")
	fs.Var(&dial, "dial", "address that must be unreachable (repeatable)")
	fs.StringVar(&p.Lookup, "lookup", "example.org", "name that must not resolve")
	fs.IntVar(&p.PidsLimit, "pids-limit", 128, "container pids limit")
	if err := fs.Parse(args); err != nil {
		return 2
	}
	p.Dial = dial
	return emit(buildReport(p))
}

func emit(r report) int {
	if err := json.NewEncoder(os.Stdout).Encode(r); err != nil {
		return 1
	}
	return 0
}

func buildReport(p params) report {
	r := report{Info: map[string]string{}}
	add := func(c check) { r.Checks = append(r.Checks, c) }
	for _, c := range readChecks(p) {
		add(c)
	}
	add(secretCheck(p.Secret))
	for _, c := range networkChecks(p) {
		add(c)
	}
	for _, c := range writeChecks() {
		add(c)
	}
	for _, c := range privilegeChecks() {
		add(c)
	}
	if !p.SkipForkBomb {
		add(forkBombCheck(p.PidsLimit))
	}
	collectInfo(r.Info)
	return r
}

func denied(name string, err error) check {
	if err == nil {
		return check{Name: name, Breach: true, Detail: "the action succeeded"}
	}
	return check{Name: name, Errno: errnoName(err), Detail: "denied"}
}

func readChecks(p params) []check {
	var out []check
	for name, path := range map[string]string{"read_host_canary": p.Canary, "read_other_job_dir": p.JobCanary} {
		if path == "" {
			continue
		}
		_, err := os.ReadFile(path)
		out = append(out, denied(name, err))
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
	return out
}

// secretCheck looks for another container's secret in this process's
// environment and in the environment of every process it can see.
func secretCheck(secret string) check {
	c := check{Name: "env_secret_of_other_container"}
	if secret == "" {
		return c
	}
	entries, _ := os.ReadDir("/proc")
	for _, e := range entries {
		if !isPID(e.Name()) {
			continue
		}
		if data, err := os.ReadFile("/proc/" + e.Name() + "/environ"); err == nil && strings.Contains(string(data), secret) {
			c.Breach, c.Detail = true, "the secret is in the environment of pid "+e.Name()
		}
	}
	return c
}

func networkChecks(p params) []check {
	var out []check
	for _, addr := range p.Dial {
		conn, err := net.DialTimeout("tcp", addr, 3*time.Second)
		if err == nil {
			conn.Close()
		}
		out = append(out, denied("connect:"+addr, err))
	}
	if p.Lookup != "" {
		_, err := net.LookupHost(p.Lookup)
		out = append(out, denied("dns:"+p.Lookup, err))
	}
	return out
}

func writeChecks() []check {
	var out []check
	for _, path := range []string{"/probe-write", "/etc/probe-write", "/usr/local/bin/probe-write",
		"/opt/renderer/templates/probe-write", "/opt/renderer/configurations/probe-write"} {
		err := os.WriteFile(path, []byte("x"), 0o600)
		if err == nil {
			_ = os.Remove(path)
		}
		out = append(out, denied("write:"+path, err))
	}
	return out
}

func privilegeChecks() []check {
	out := []check{
		denied("setuid_root", rawSyscall(syscall.SYS_SETUID, 0)),
		denied("mount", mountTmpfs()),
		denied("mknod", mknodDevice()),
		denied("chown_root", chownRoot()),
		denied("user_namespace", userNamespace()),
		execFromTmpfs("exec_from_work", "/work"),
		execFromTmpfs("exec_from_tmp", "/tmp"),
		ptraceCheck(),
	}
	return append(out, statusChecks()...)
}

func rawSyscall(trap uintptr, args ...uintptr) error {
	var a [3]uintptr
	copy(a[:], args)
	if _, _, errno := syscall.RawSyscall(trap, a[0], a[1], a[2]); errno != 0 {
		return errno
	}
	return nil
}

func mountTmpfs() error {
	dir := "/work/probe-mnt"
	if err := os.MkdirAll(dir, 0o700); err != nil {
		return err
	}
	defer os.Remove(dir)
	return syscall.Mount("tmpfs", dir, "tmpfs", 0, "")
}

func mknodDevice() error {
	path := "/work/probe-null"
	defer os.Remove(path)
	// character device 1:3 is /dev/null
	return syscall.Mknod(path, syscall.S_IFCHR|0o600, 1<<8|3)
}

func chownRoot() error {
	path := "/work/probe-owner"
	if err := os.WriteFile(path, []byte("x"), 0o600); err != nil {
		return err
	}
	defer os.Remove(path)
	return os.Chown(path, 0, 0)
}

func userNamespace() error {
	cmd := exec.Command("/proc/self/exe", "hold")
	cmd.SysProcAttr = &syscall.SysProcAttr{Cloneflags: syscall.CLONE_NEWUSER}
	if err := cmd.Start(); err != nil {
		return err
	}
	_ = cmd.Process.Kill()
	_ = cmd.Wait()
	return nil
}

// execFromTmpfs copies this binary to a tmpfs and tries to run it. tmpfs
// mounts are noexec unless the Compose file says otherwise.
func execFromTmpfs(name, dir string) check {
	self, err := os.ReadFile("/proc/self/exe")
	if err != nil {
		return check{Name: name, Detail: "cannot read own binary: " + errnoName(err)}
	}
	path := filepath.Join(dir, "probe-exec")
	if err := os.WriteFile(path, self, 0o700); err != nil {
		return check{Name: name, Detail: "cannot write: " + errnoName(err)}
	}
	defer os.Remove(path)
	cmd := exec.Command(path, "hold")
	if err := cmd.Start(); err != nil {
		return denied(name, err)
	}
	_ = cmd.Process.Kill()
	_ = cmd.Wait()
	return denied(name, nil)
}

// statusChecks reads the process status: no capability of any set, no new
// privileges, a seccomp filter, and not root.
func statusChecks() []check {
	status := procStatus()
	var out []check
	for _, key := range []string{"CapInh", "CapPrm", "CapEff", "CapBnd", "CapAmb"} {
		out = append(out, check{Name: "capabilities:" + key, Breach: strings.Trim(status[key], "0") != "", Detail: status[key]})
	}
	out = append(out,
		check{Name: "no_new_privileges", Breach: status["NoNewPrivs"] != "1", Detail: status["NoNewPrivs"]},
		check{Name: "seccomp_filter", Breach: status["Seccomp"] != "2", Detail: status["Seccomp"]},
		check{Name: "not_root", Breach: strings.Fields(status["Uid"])[0] == "0", Detail: status["Uid"]},
	)
	return out
}

func procStatus() map[string]string {
	out := map[string]string{"Uid": "0"}
	data, err := os.ReadFile("/proc/self/status")
	if err != nil {
		return out
	}
	for _, line := range strings.Split(string(data), "\n") {
		if key, value, ok := strings.Cut(line, ":"); ok {
			out[key] = strings.TrimSpace(value)
		}
	}
	return out
}

func collectInfo(info map[string]string) {
	for key, paths := range map[string][]string{
		"memory_max": {"/sys/fs/cgroup/memory.max", "/sys/fs/cgroup/memory/memory.limit_in_bytes"},
		"pids_max":   {"/sys/fs/cgroup/pids.max", "/sys/fs/cgroup/pids/pids.max"},
		"cpu_max":    {"/sys/fs/cgroup/cpu.max", "/sys/fs/cgroup/cpu/cpu.cfs_quota_us"},
	} {
		for _, path := range paths {
			if data, err := os.ReadFile(path); err == nil {
				info[key] = strings.TrimSpace(string(data))
				break
			}
		}
	}
	info["work_bytes"] = fsSize("/work")
	info["tmp_bytes"] = fsSize("/tmp")
	info["work_writable"] = writable("/work")
	info["tmp_writable"] = writable("/tmp")
	var names []string
	for _, kv := range os.Environ() {
		name, _, _ := strings.Cut(kv, "=")
		names = append(names, name)
	}
	sort.Strings(names)
	info["env_names"] = strings.Join(names, ",")
	info["uid"] = fmt.Sprint(os.Getuid())
}

func fsSize(path string) string {
	var st syscall.Statfs_t
	if err := syscall.Statfs(path, &st); err != nil {
		return "error " + errnoName(err)
	}
	return fmt.Sprint(uint64(st.Blocks) * uint64(st.Bsize))
}

func writable(dir string) string {
	path := filepath.Join(dir, "probe-writable")
	if err := os.WriteFile(path, []byte("x"), 0o600); err != nil {
		return "no " + errnoName(err)
	}
	_ = os.Remove(path)
	return "yes"
}
